def _feishu_realtime_cards_enabled(user_config: dict | None) -> bool:
    """Return the explicit Feishu realtime-card switch without inheritance."""
    display = (user_config or {}).get("display") or {}
    platforms = display.get("platforms") or {}
    feishu = platforms.get("feishu") or {}
    return feishu.get("realtime_cards") is True


def _render_feishu_status(agent: Any, phase: str, detail: str | None = None) -> str:
    """Render a status card from the current agent snapshot."""
    try:
        from gateway.feishu_realtime_display import render_status_card

        compressor = getattr(agent, "context_compressor", None)
        return render_status_card(
            phase=phase,
            model=getattr(agent, "model", None),
            provider=getattr(agent, "provider", None),
            used_tokens=getattr(compressor, "last_prompt_tokens", 0) if compressor else 0,
            context_length=getattr(compressor, "context_length", 0) if compressor else 0,
            detail=detail,
        )
    except Exception:
        # The card is optional UX; a renderer failure must never affect a turn.
        return str(detail or "⏳ 已收到，正在思考...")


async def _send_or_update_feishu_status_coro(ctx, content: str):
    """Create once, then edit the realtime status card for this turn."""
    adapter = ctx._status_adapter
    if not adapter or not ctx._feishu_realtime_cards:
        return
    lock = ctx._feishu_status_lock
    if lock is None:
        return
    async with lock:
        message_id = ctx._feishu_status_message_id[0]
        if message_id:
            result = await adapter.edit_message(
                ctx._status_chat_id,
                message_id,
                content,
                finalize=False,
            )
            if result.success:
                return
            logger.debug("[Feishu] realtime status edit failed: %s", result.error)
            # Do not send a second status bubble after an edit failure.
            return
        result = await adapter.send(
            ctx._status_chat_id,
            content,
            metadata=ctx._status_thread_metadata,
        )
        if result.success and result.message_id:
            ctx._feishu_status_message_id[0] = result.message_id


